\section*{Algorithm Name}
\textbf{Stochastic Gradient Descent (SGD) with Fixed Step Size for Strongly Convex \& Smooth Objectives}

\section*{Mathematical Formulation}
Let 
\[
F(w) \;=\; \mathbb{E}_{\xi}\big[ f(w;\xi) \big],\qquad w\in\R^{d},
\]
where each stochastic component $f(\cdot;\xi)$ is differentiable.  
At iteration $t=0,1,2,\dots$ a minibatch $\xi_t$ is drawn independently and the stochastic gradient is
\[
g_t \;:=\; \nabla f(w_t;\xi_t).
\]
The update rule with a \emph{fixed} stepsize $\eta>0$ is
\begin{equation}
\boxed{\,w_{t+1}= w_t - \eta\, g_t\,}. \label{eq:update}
\end{equation}
The algorithm stops after a pre‑specified number $T$ of iterations or when a tolerance on $\|g_t\|$ is met.

\section*{Pseudocode}
\begin{algorithm}[H]
\caption{SGD with Fixed Step Size}
\begin{algorithmic}[1]
\State \textbf{Input:} initial point $w_0\in\R^{d}$, stepsize $\eta>0$, number of iterations $T$.
\For{$t=0$ \textbf{to} $T-1$}
    \State Sample a minibatch $\xi_t$ (i.i.d. from the data distribution).
    \State Compute stochastic gradient $g_t \gets \nabla f(w_t;\xi_t)$.
    \State Update $w_{t+1} \gets w_t - \eta\, g_t$.\label{alg:update}
\EndFor
\State \textbf{Output:} $w_T$ (or the average $\bar w_T=\frac1T\sum_{t=1}^T w_t$).
\end{algorithmic}
\end{algorithm}

\section*{Dry Run Example}
Consider the one‑dimensional quadratic
\[
F(w) = (w-3)^2,
\]
so that $\nabla F(w)=2(w-3)$.  
Take $w_0=0$, stepsize $\eta=0.1$, and assume the stochastic gradient equals the true gradient (i.e. no noise).  

\begin{center}
\begin{tabular}{c|c|c|c}
$t$ & $g_t=2(w_t-3)$ & $w_{t+1}=w_t-\eta g_t$ & $F(w_{t+1})$ \\ \hline
0 & $-6$ & $0-0.1(-6)=0.6$ & $(0.6-3)^2=5.76$\\
1 & $2(0.6-3)=-4.8$ & $0.6-0.1(-4.8)=1.08$ & $(1.08-3)^2=3.6864$\\
2 & $2(1.08-3)=-3.84$ & $1.08-0.1(-3.84)=1.464$ & $(1.464-3)^2\approx2.3665$
\end{tabular}
\end{center}
The iterates move steadily toward the optimum $w^{*}=3$ and the objective value decreases at each step.

