\section*{Assumptions}
\begin{assumption}[Strong Convexity]\label{ass:strong}
$F$ is $\mu$‑strongly convex ($\mu>0$), i.e.
\[
F(y)\ge F(x)+\langle\nabla F(x),y-x\rangle+\frac{\mu}{2}\|y-x\|^{2},
\qquad\forall x,y\in\R^{d}.
\]
\end{assumption}
\begin{assumption}[Smoothness]\label{ass:smooth}
$F$ has $L$‑Lipschitz gradients ($L>0$), i.e.
\[
\|\nabla F(x)-\nabla F(y)\|\le L\|x-y\|,
\qquad\forall x,y\in\R^{d}.
\]
Equivalently,
\[
F(y)\le F(x)+\langle\nabla F(x),y-x\rangle+\frac{L}{2}\|y-x\|^{2}.
\]
\end{assumption}
\begin{assumption}[Unbiased Stochastic Gradient]\label{ass:unbiased}
\[
\E\!\left[\,g_t\mid w_t\,\right]=\nabla F(w_t),\qquad \forall t.
\]
\end{assumption}
\begin{assumption}[Bounded Variance]\label{ass:variance}
There exists $\sigma^{2}\ge0$ such that
\[
\E\!\left[\|g_t-\nabla F(w_t)\|^{2}\mid w_t\right]\le\sigma^{2},
\qquad \forall t.
\]
\end{assumption}
\begin{assumption}[Stepsize]\label{ass:stepsize}
The fixed stepsize satisfies
\[
0<\eta<\frac{2}{L+\mu}.
\]
For simplicity we shall later use the more restrictive bound $\eta\le \frac{1}{2L}$.
\end{assumption}

\section*{Main Convergence Theorem}
\begin{theorem}[Linear Convergence to a Neighborhood]\label{thm:main}
Under Assumptions \ref{ass:strong}–\ref{ass:stepsize}, let $\{w_t\}$ be generated by \eqref{eq:update}. Define the optimal point $w^{*}=\arg\min_{w}F(w)$. Then for every $t\ge0$
\begin{align}
\E\!\big[\|w_{t}-w^{*}\|^{2}\big] 
&\le (1-\eta\mu)^{t}\,\|w_{0}-w^{*}\|^{2}
   \;+\; \frac{\eta\sigma^{2}}{\mu}. \label{eq:dist-bound}
\end{align}
Consequently, the expected suboptimality satisfies
\begin{align}
\E\!\big[F(w_{t})-F(w^{*})\big]
&\le \frac{L}{2}\,(1-\eta\mu)^{t}\,\|w_{0}-w^{*}\|^{2}
   \;+\; \frac{\eta L\sigma^{2}}{2\mu}. \label{eq:obj-bound}
\end{align}
\end{theorem}

\section*{Theoretical Properties}
\begin{itemize}[leftmargin=*]
\item \textbf{Stability:} The recursion \eqref{eq:dist-bound} is a contraction with factor $1-\eta\mu<1$, guaranteeing that the iterates remain bounded.
\item \textbf{Hyperparameter Sensitivity:} Larger $\eta$ accelerates the contraction term $(1-\eta\mu)^{t}$ but inflates the steady‑state error $\frac{\eta\sigma^{2}}{\mu}$. The optimal constant stepsize (in the sense of minimizing the right‑hand side of \eqref{eq:dist-bound}) is $\eta^{\star}= \min\big\{\frac{1}{2L},\,\frac{\mu}{\sigma^{2}}\,\big\}$.
\item \textbf{Comparison to Baselines:}
    \begin{enumerate}
        \item \emph{Deterministic Gradient Descent} (no noise, $\sigma=0$) enjoys pure linear convergence $\|w_t-w^{*}\|^{2}\le (1-\eta\mu)^{t}\|w_0-w^{*}\|^{2}$.
        \item \emph{Decaying stepsize SGD} ($\eta_t\downarrow0$) can drive the error to zero, but at a slower $O(1/t)$ rate. The constant‑stepsize scheme trades asymptotic exactness for faster geometric decay up to a noise‑dependent floor.
    \end{enumerate}
\end{itemize}

\section*{Discussion}
The theorem shows that for strongly convex and smooth objectives, a simple fixed‑stepsize SGD algorithm converges \emph{linearly} to a neighbourhood whose radius is proportional to $\eta\sigma^{2}/\mu$. The result is sharp: if the variance term vanishes, the bound reduces to the classic deterministic linear rate. Moreover, the dependence on the condition number $\kappa=L/\mu$ appears only through the contraction factor $1-\eta\mu$, illustrating that choosing $\eta\approx 1/L$ yields a factor $1-1/\kappa$ per iteration.

