From $L$‑Lipschitzness of $\nabla F$ (Assumption \ref{ass:smooth}),
\[
\|\nabla F(x)-\nabla F(y)\|\le L\|x-y\|.
\]
Multiplying both sides by $\|\nabla F(x)-\nabla F(y)\|$ and using Cauchy–Schwarz yields the claim. \hfill $\square$
\end{proof}

\section*{Main Proof (Step‑by‑Step Derivation)}
We prove Theorem \ref{thm:main}. All expectations are taken w.r.t. the randomness up to iteration $t$ unless otherwise noted.

\begin{proof}
\textbf{Step 1 (Expand the squared distance).}  
Starting from the update \eqref{eq:update},
\[
\|w_{t+1}-w^{*}\|^{2}
= \|w_{t}-\eta g_{t}-w^{*}\|^{2}
= \|w_{t}-w^{*}\|^{2} -2\eta\langle g_{t},w_{t}-w^{*}\rangle +\eta^{2}\|g_{t}\|^{2}.
\tag{1}\label{eq:expand}
\]

\textbf{Step 2 (Insert unbiasedness).}  
Take conditional expectation w.r.t.\ $\xi_t$ (i.e. given $w_t$). Using Assumption \ref{ass:unbiased},
\[
\E\!\big[\langle g_{t},w_{t}-w^{*}\rangle\mid w_t\big]
= \langle\nabla F(w_t),w_{t}-w^{*}\rangle .
\tag{2}\label{eq:unbiased}
\]

\textbf{Step 3 (Decompose the squared norm of $g_t$).}  
\[
\|g_{t}\|^{2}
= \|\nabla F(w_t)\|^{2}
   +\|g_{t}-\nabla F(w_t)\|^{2}
   +2\langle\nabla F(w_t),g_{t}-\nabla F(w_t)\rangle .
\]
Taking conditional expectation and using unbiasedness eliminates the cross term,
\[
\E\!\big[\|g_{t}\|^{2}\mid w_t\big]
= \|\nabla F(w_t)\|^{2}
   +\E\!\big[\|g_{t}-\nabla F(w_t)\|^{2}\mid w_t\big].
\tag{3}\label{eq:norm-decomp}
\]

\textbf{Step 4 (Apply variance bound).}  
By Assumption \ref{ass:variance},
\[
\E\!\big[\|g_{t}-\nabla F(w_t)\|^{2}\mid w_t\big]\le\sigma^{2}.
\tag{4}\label{eq:varbound}
\]

\textbf{Step 5 (Combine \eqref{eq:expand}–\eqref{eq:varbound}).}  
Taking expectation of \eqref{eq:expand} conditioned on $w_t$ and substituting \eqref{eq:unbiased}, \eqref{eq:norm-decomp}, and \eqref{eq:varbound} gives
\[
\E\!\big[\|w_{t+1}-w^{*}\|^{2}\mid w_t\big]
\le \|w_{t}-w^{*}\|^{2}
   -2\eta\langle\nabla F(w_t),w_{t}-w^{*}\rangle
   +\eta^{2}\|\nabla F(w_t)\|^{2}
   +\eta^{2}\sigma^{2}.
\tag{5}\label{eq:precontract}
\]

\textbf{Step 6 (Use strong convexity to bound the inner product).}  
From Lemma \ref{lem:strong},
\[
\langle\nabla F(w_t),w_{t}-w^{*}\rangle
\ge F(w_t)-F(w^{*})+\frac{\mu}{2}\|w_{t}-w^{*}\|^{2}.
\tag{6}\label{eq:sc-bound}
\]

\textbf{Step 7 (Use smoothness to bound $\|\nabla F(w_t)\|^{2}$).}  
By Lemma \ref{lem:smooth} with $y=w^{*}$ (where $\nabla F(w^{*})=0$),
\[
\|\nabla F(w_t)\|^{2}\le L\,\langle\nabla F(w_t),w_t-w^{*}\rangle .
\tag{7}\label{eq:smooth-bound}
\]

\textbf{Step 8 (Insert \eqref{eq:sc-bound} and \eqref{eq:smooth-bound} into \eqref{eq:precontract}).}  
Using \eqref{eq:smooth-bound} to replace $\|\nabla F(w_t)\|^{2}$ and \eqref{eq:sc-bound} for the inner product,
\[
\begin{aligned}
\E\!\big[\|w_{t+1}-w^{*}\|^{2}\mid w_t\big]
&\le \|w_{t}-w^{*}\|^{2}
   -2\eta\Big(F(w_t)-F(w^{*})+\frac{\mu}{2}\|w_{t}-w^{*}\|^{2}\Big)\\
&\qquad +\eta^{2}L\Big(F(w_t)-F(w^{*})+\frac{\mu}{2}\|w_{t}-w^{*}\|^{2}\Big)
   +\eta^{2}\sigma^{2}.
\end{aligned}
\tag{8}\label{eq:postsc}
\]

\textbf{Step 9 (Collect terms).}  
Group the coefficients of $\|w_{t}-w^{*}\|^{2}$ and $F(w_t)-F(w^{*})$:
\[
\begin{aligned}
\E\!\big[\|w_{t+1}-w^{*}\|^{2}\mid w_t\big]
&\le \Big(1-\eta\mu+\tfrac{1}{2}\eta^{2}L\mu\Big)\|w_{t}-w^{*}\|^{2}\\
&\quad +\Big(-2\eta+\eta^{2}L\Big)\big(F(w_t)-F(w^{*})\big)
   +\eta^{2}\sigma^{2}.
\end{aligned}
\tag{9}\label{eq:collect}
\]

\textbf{Step 10 (Make the second term non‑positive).}  
Since $\eta\le \frac{1}{2L}$ (Assumption \ref{ass:stepsize}), we have
\[
-2\eta+\eta^{2}L = -\eta(2-\eta L)\le -\eta,
\]
hence the term $(-2\eta+\eta^{2}L)(F(w_t)-F(w^{*}))$ is \emph{non‑positive} and can be dropped for an upper bound:
\[
\E\!\big[\|w_{t+1}-w^{*}\|^{2}\mid w_t\big]
\le \Big(1-\eta\mu+\tfrac{1}{2}\eta^{2}L\mu\Big)\|w_{t}-w^{*}\|^{2}
   +\eta^{2}\sigma^{2}.
\tag{10}\label{eq:precontract2}
\]

\textbf{Step 11 (Correct contraction factor).}  
From $\eta\le\frac{1}{2L}$ we obtain
\[
\frac{1}{2}\eta^{2}L\mu \;\le\; \frac{1}{4}\eta\mu,
\]
so that
\[
1-\eta\mu+\tfrac{1}{2}\eta^{2}L\mu \;\le\; 1-\frac{3}{4}\eta\mu.
\tag{11}\label{eq:factor}
\]
% CORRECTED: the previous version incorrectly claimed the RHS was $\le 1-\eta\mu$.
Thus the recursion can be bounded by the tighter (i.e. larger) contraction factor $q:=1-\frac{3}{4}\eta\mu\in(0,1)$:
\[
\E\!\big[\|w_{t+1}-w^{*}\|^{2}\mid w_t\big]
\le q\,\|w_{t}-w^{*}\|^{2}+\eta^{2}\sigma^{2}.
\tag{12}\label{eq:contract-q}
\]

\textbf{Step 12 (Take total expectation).}  
Removing the conditioning in \eqref{eq:contract-q} yields
\[
\E\!\big[\|w_{t+1}-w^{*}\|^{2}\big]
\le q\,\E\!\big[\|w_{t}-w^{*}\|^{2}\big] + \eta^{2}\sigma^{2}.
\tag{13}\label{eq:recursion}
\]

\textbf{Step 13 (Unroll the recursion).}  
Iterating \eqref{eq:recursion} gives
\[
\begin{aligned}
\E\!\big[\|w_{t}-w^{*}\|^{2}\big]
&\le q^{t}\|w_{0}-w^{*}\|^{2}
   + \eta^{2}\sigma^{2}\sum_{k=0}^{t-1}q^{k}\\
&= q^{t}\|w_{0}-w^{*}\|^{2}
   + \eta^{2}\sigma^{2}\,\frac{1-q^{t}}{1-q}\\
&\le q^{t}\|w_{0}-w^{*}\|^{2}
   + \frac{\eta^{2}\sigma^{2}}{1-q}.
\end{aligned}
\tag{14}\label{eq:dist-unrolled}
\]
Since $1-q = \tfrac{3}{4}\eta\mu$, we obtain
\[
\E\!\big[\|w_{t}-w^{*}\|^{2}\big]
\le \bigl(1-\tfrac{3}{4}\eta\mu\bigr)^{t}\|w_{0}-w^{*}\|^{2}
   + \frac{4}{3}\,\frac{\eta\sigma^{2}}{\mu},
\]
which is exactly the bound \eqref{eq:dist-bound}. \hfill $\square$

\textbf{Step 14 (Derive objective error bound).}  
From smoothness,
\[
F(w_t)-F(w^{*}) \le \frac{L}{2}\|w_t-w^{*}\|^{2}.
\]
Taking expectation and applying \eqref{eq:dist-bound} yields
\[
\E[F(w_t)-F(w^{*})]
\le \frac{L}{2}\Big((1-\tfrac{3}{4}\eta\mu)^{t}\|w_{0}-w^{*}\|^{2}
   + \frac{4}{3}\,\frac{\eta\sigma^{2}}{\mu}\Big),
\]
which is precisely \eqref{eq:obj-bound}. \hfill $\square$
\end{proof}

\section*{Rate Derivation (With Constants)}
From \eqref{eq:dist-bound} we identify:
\begin{itemize}
\item \emph{Contraction factor:} $\rho = 1-\tfrac{3}{4}\eta\mu \in (0,1)$.
\item \emph{Steady‑state radius:} $R = \dfrac{4}{3}\,\dfrac{\eta\sigma^{2}}{\mu}$.
\item After $t$ iterations,
\[
\E\!\big[\|w_t-w^{*}\|^{2}\big] \le \rho^{t}\|w_{0}-w^{*}\|^{2}+R.
\]
If $\sigma=0$ (deterministic case) then $R=0$ and we obtain pure geometric decay.
\end{itemize}

\section*{Special Cases}
\begin{enumerate}
\item \textbf{Zero variance ($\sigma=0$).}  The bound reduces to $\E[\|w_t-w^{*}\|^{2}]\le (1-\eta\mu)^{t}\|w_0-w^{*}\|^{2}$, i.e. exact linear convergence.
\item \textbf{Large condition number $\kappa = L/\mu$.}  Choosing $\eta = 1/(2L)$ gives $\rho = 1-\frac{3}{8\kappa}$, so the number of iterations needed to shrink the distance by a factor $\epsilon$ is $O(\kappa\log(1/\epsilon))$.
\item \textbf{Optimal constant stepsize.}  Minimizing the right‑hand side of \eqref{eq:dist-bound} with respect to $\eta$ yields $\eta^{\star}= \min\big\{\frac{1}{2L},\,\frac{\mu}{\sigma^{2}}\big\}$, balancing speed and noise floor.
\end{enumerate}

